  SopTerkait: 'SopTerkait',
  LangkahSOP: 'LangkahSOP',
  Pelaksana: 'Pelaksana',
  DetailSOPPelaksana: 'DetailSOPPelaksana',
  LogEditSOP: 'LogEditSOP',
  LogEditSopDomainField: 'LogEditSopDomainField',
  PengajuanEvaluasi: 'PengajuanEvaluasi',
  NilaiEvaluasi: 'NilaiEvaluasi',
  LogNilaiEvaluasi: 'LogNilaiEvaluasi',
  DokumenTte: 'DokumenTte',
  RiwayatTandaTangan: 'RiwayatTandaTangan',
  KonfigurasiDiagramSOP: 'KonfigurasiDiagramSOP',
  OverridePanahDiagramSOP: 'OverridePanahDiagramSOP',
